import scipy.ndimage
from skimage.transform import rescale, resize, rotate
from skimage.util import pad
import numpy as np
import cv2

class Augmentor:
    def __init__(self, image):
        self.image = image

    def affine_transform(self, mat, size, pad_value=0):
        return scipy.ndimage.affine_transform(self.image, mat, output_shape=size, mode="constant", cval=pad_value)

    def flip_horizontal(self):
        return cv2.flip(self.image, 1)

    def flip_vertical(self):
